#!/usr/bin/env node
/**
 * Sprint 3 migration: create campaigns, campaign_assets, campaign_leads tables on Aurora DSQL.
 * Aurora DSQL does not support foreign keys, CREATE TYPE, or serial sequences.
 * All IDs are UUIDs generated by gen_random_uuid().
 */
import { execFileSync } from 'node:child_process';
import { config } from 'dotenv';
import { existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import pkg from 'pg';
const { Client } = pkg;

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
config({ path: resolve(root, '.env') });
const prodEnv = resolve(root, '.env.production');
if (existsSync(prodEnv)) config({ path: prodEnv, override: true });
const prodProdEnv = resolve(root, '.env.production.prod');
if (existsSync(prodProdEnv)) config({ path: prodProdEnv, override: true });

const host   = process.env.AURORA_DSQL_HOST?.trim();
const region = process.env.AURORA_DSQL_REGION?.trim() || 'ap-southeast-2';

if (!host) { console.error('AURORA_DSQL_HOST not set'); process.exit(1); }

console.log(`Generating DSQL IAM token for ${host}…`);
const token = execFileSync('aws', [
  'dsql', 'generate-db-connect-admin-auth-token',
  '--hostname', host,
  '--region',   region,
  '--expires-in', '900',
], { encoding: 'utf8' }).trim();

const client = new Client({
  host,
  port: 5432,
  database: 'postgres',
  user: 'admin',
  password: token,
  ssl: { rejectUnauthorized: false },
});

await client.connect();
console.log('Connected to Aurora DSQL.');

const migrations = [
  // campaigns
  `CREATE TABLE IF NOT EXISTS campaigns (
    id                  TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
    title               TEXT        NOT NULL,
    platform            TEXT        NOT NULL,
    "campaignType"      TEXT        NOT NULL,
    "campaignSubtype"   TEXT,
    status              TEXT        NOT NULL DEFAULT 'DRAFT',
    objective           TEXT,
    "budgetType"        TEXT        NOT NULL DEFAULT 'DAILY',
    "budgetAmount"      DOUBLE PRECISION,
    currency            TEXT        NOT NULL DEFAULT 'NZD',
    "startDate"         TIMESTAMPTZ,
    "endDate"           TIMESTAMPTZ,
    "targetAudience"    TEXT,
    "platformConfig"    TEXT,
    "externalCampaignId" TEXT,
    "externalAdSetId"   TEXT,
    "externalAdId"      TEXT,
    "listingIds"        TEXT        NOT NULL DEFAULT '[]',
    headline            TEXT,
    "primaryText"       TEXT,
    description         TEXT,
    "callToAction"      TEXT,
    "destinationUrl"    TEXT,
    "leadFormConfig"    TEXT,
    notes               TEXT,
    "createdBy"         TEXT,
    "createdAt"         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id)
  )`,

  // campaign_assets
  `CREATE TABLE IF NOT EXISTS campaign_assets (
    id            TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
    "campaignId"  TEXT        NOT NULL,
    "assetType"   TEXT        NOT NULL,
    url           TEXT        NOT NULL,
    "thumbnailUrl" TEXT,
    format        TEXT,
    width         INT,
    height        INT,
    "durationSec" INT,
    "fileSize"    INT,
    "mimeType"    TEXT,
    "sortOrder"   INT         NOT NULL DEFAULT 0,
    "createdAt"   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id)
  )`,

  // campaign_leads
  `CREATE TABLE IF NOT EXISTS campaign_leads (
    id            TEXT        NOT NULL DEFAULT gen_random_uuid()::text,
    "campaignId"  TEXT        NOT NULL,
    platform      TEXT        NOT NULL,
    "listingId"   TEXT,
    "leadFormId"  TEXT,
    "fullName"    TEXT,
    email         TEXT,
    phone         TEXT,
    message       TEXT,
    "extraFields" TEXT,
    "rawPayload"  TEXT,
    status        TEXT        NOT NULL DEFAULT 'NEW',
    notes         TEXT,
    "createdAt"   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id)
  )`,

  // index for listing campaigns by platform
  `CREATE INDEX ASYNC IF NOT EXISTS idx_campaigns_platform ON campaigns (platform)`,
  `CREATE INDEX ASYNC IF NOT EXISTS idx_campaigns_status   ON campaigns (status)`,
  `CREATE INDEX ASYNC IF NOT EXISTS idx_campaign_leads_campaign ON campaign_leads ("campaignId")`,
  `CREATE INDEX ASYNC IF NOT EXISTS idx_campaign_assets_campaign ON campaign_assets ("campaignId")`,
];

for (const sql of migrations) {
  const label = sql.slice(0, 60).replace(/\s+/g, ' ');
  console.log(`  ▶ ${label}…`);
  await client.query(sql);
  console.log('    ✓');
}

await client.end();
console.log('✅  Sprint 3 campaign tables migration complete.');
